const fixture = (index = 1): IOptionEWorkplanDraftV3Aggregate => JSON.parse(fixtures[index].body) as IOptionEWorkplanDraftV3Aggregate;
const hash = (body: string): string => createHash('sha256').update(body, 'utf8').digest('hex').toUpperCase();
const hasher = { sha256Hex: async (body: string): Promise<string> => hash(body).toLowerCase() };
describe('standalone private V3 exact payload codec', () => {
    test.each(fixtures)('preserves issued $name byte/hash golden and detached reopen', async (golden) => {
        const input = JSON.parse(golden.body) as IOptionEWorkplanDraftV3Aggregate;
        expect(hash(golden.body)).toBe(golden.hash);
        expect(canonicaliseOptionEPartialDraftV3(input)).toBe(golden.body);
        const prepared = await prepareOptionEPartialDraftV3(input, hasher);
        expect(prepared).toEqual({ schemaVersion: 'demo.workplan-draft/v3', aggregate: input,
            payloadJson: golden.body, payloadSha256: golden.hash });
        expect(Object.keys(prepared).sort()).toEqual(['aggregate', 'payloadJson', 'payloadSha256', 'schemaVersion']);
        expect(prepared.aggregate).not.toBe(input);
        expect(await reopenOptionEPartialDraftV3('demo.workplan-draft/v3', golden.body, golden.hash.toLowerCase(), hasher)).toEqual(prepared);
        expect(parseCanonicalOptionEPartialDraftV3(golden.body)).toEqual(input);
    });
    test('retains dual native values, independent editor text, zero/unset and all rich fields', async () => {
        const input = fixture();
        const prepared = await prepareOptionEPartialDraftV3(input, hasher);
        const reopened = await reopenOptionEPartialDraftV3('demo.workplan-draft/v3', prepared.payloadJson, prepared.payloadSha256, hasher);
        expect(reopened.aggregate).toEqual(input);
        expect(reopened.aggregate.core.entries[0].nativeRole).toBe('Contributor');
        expect(reopened.aggregate.core.entries[0].targets.annual).toEqual({ kind: 'NativePair', numericValue: 0,
            textValue: 'zero recorded separately', success: '', editorText: '' });
        expect(reopened.aggregate.impact[0].personalItemWeight).toBe(0);
        expect(reopened.aggregate.impact[0].activeInWorkplan).toBe(false);
        expect(reopened.aggregate.impact[0].description).toBe('Historical intended outcome');
        expect(reopened.aggregate.impact[0].editorDefinition.intendedOutcome).toBe('Unfinished changed outcome');
        expect(reopened.aggregate.behaviours.entries[0].periodCommitments.H1).toBe('Retained H1');
        expect(reopened.aggregate.core.entries[0].nativeQuarterOrder).toEqual(['Q3', 'Q1']);
    });
    test('preserves absent weight and scalar type distinctions, without defaulting or mutation', () => {
        const input = fixture(0);
        input.impact[0].targets.annual = { kind: 'Scalar', value: 0 };
        input.impact[0].targets.q1 = { kind: 'Scalar', value: '0' };
        input.impact[0].targets.q2 = { kind: 'Scalar', value: '' };
        input.employeeNotes = { categoryWeightReason: '', zeroPersonalReason: undefined };
        const before = JSON.stringify(input);
        const read = parseCanonicalOptionEPartialDraftV3(canonicaliseOptionEPartialDraftV3(input));
        expect(read.impact[0].targets).toEqual(input.impact[0].targets);
        expect(Object.prototype.hasOwnProperty.call(read.impact[0], 'personalItemWeight')).toBe(false);
        expect(read.employeeNotes).toEqual({ categoryWeightReason: '' });
        expect(JSON.stringify(input)).toBe(before);
        expect(Object.prototype.hasOwnProperty.call(input.employeeNotes, 'zeroPersonalReason')).toBe(true);
    });
    test('captures bytes and full content before async hashing in reverse completion order', async () => {
        const first = fixture(), second = fixture(0);
        const releases: Array<(hash: string) => void> = [];
        const captured: string[] = [];
        const hashing = { sha256Hex: (body: string): Promise<string> => {
                captured.push(body);
                return new Promise(resolve => releases.push(resolve));
            } };
        const a = prepareOptionEPartialDraftV3(first, hashing), b = prepareOptionEPartialDraftV3(second, hashing);
        first.impact[0].personalItemWeight = 77;
        second.impact[0].wording = 'Later edit';
        releases[1](hash(captured[1]));
        const rb = await b;
        releases[0](hash(captured[0]));
        const ra = await a;
        expect(ra.payloadJson).toBe(fixtures[1].body);
        expect(rb.payloadJson).toBe(fixtures[0].body);
        expect(ra.aggregate.impact[0].personalItemWeight).toBe(0);
        expect(rb.aggregate.impact[0].wording).toBe('');
        ra.aggregate.impact[0].wording = 'Independent result';
        expect(first.impact[0].wording).toBe('\u00A3 retained result');
    });
    test('reopen captures an independent aggregate before hash awaits', async () => {
        let release!: (value: string) => void;
        const pending = reopenOptionEPartialDraftV3('demo.workplan-draft/v3', fixtures[1].body, fixtures[1].hash, { sha256Hex: () => new Promise(resolve => { release = resolve; }) });
        const other = parseCanonicalOptionEPartialDraftV3(fixtures[1].body);
        other.impact[0].wording = 'Edit';
        release(fixtures[1].hash);
        const reopened = await pending;
        expect(reopened.aggregate.impact[0].wording).toBe('\u00A3 retained result');
    });
    test('supports exactly 56000 UTF8 bytes and refuses 56001 before hashing', async () => {
        const input = fixture(0);
        input.employeeNotes = { categoryWeightReason: '' };
        const overhead = Buffer.byteLength(canonicaliseOptionEPartialDraftV3(input), 'utf8');
        input.employeeNotes.categoryWeightReason = '\u00A3'.repeat(Math.floor((56000 - overhead) / 2))
            + 'a'.repeat((56000 - overhead) % 2);
        const exact = await prepareOptionEPartialDraftV3(input, hasher);
        expect(Buffer.byteLength(exact.payloadJson, 'utf8')).toBe(56000);
        expect((await reopenOptionEPartialDraftV3('demo.workplan-draft/v3', exact.payloadJson, exact.payloadSha256, hasher)).payloadJson).toBe(exact.payloadJson);
        input.employeeNotes.categoryWeightReason += 'a';
        const hashing = jest.fn(hasher.sha256Hex);
        await expect(prepareOptionEPartialDraftV3(input, { sha256Hex: hashing })).rejects.toMatchObject({ code: 'DraftPayloadTooLarge' });
        expect(hashing).not.toHaveBeenCalled();
    });
    test.each(['{', fixtures[0].body + ' ', fixtures[0].body.replace('demo.workplan-draft/v3', 'demo.workplan-draft/v2')])('rejects malformed/noncanonical/crossed body before hashing: %s', async (body) => {
        const hashing = jest.fn(hasher.sha256Hex);
        await expect(reopenOptionEPartialDraftV3('demo.workplan-draft/v3', body, fixtures[0].hash, { sha256Hex: hashing }))
            .rejects.toMatchObject({ code: 'DraftPayloadInvalid' });
        expect(hashing).not.toHaveBeenCalled();
    });
    test('rejects declared version mismatch and digest mismatch without returning a receipt', async () => {
        await expect(reopenOptionEPartialDraftV3('demo.workplan-draft/v2' as 'demo.workplan-draft/v3', fixtures[0].body, fixtures[0].hash, hasher))
            .rejects.toMatchObject({ code: 'DraftPayloadInvalid' });
        await expect(reopenOptionEPartialDraftV3('demo.workplan-draft/v3', fixtures[0].body, '0'.repeat(64), hasher))
            .rejects.toMatchObject({ code: 'DraftPayloadInvalid' });
    });
    test('rejects malformed digest and propagates provider failure on both async entry points', async () => {
        await expect(prepareOptionEPartialDraftV3(fixture(0), { sha256Hex: async () => 'bad' }))
            .rejects.toMatchObject({ code: 'DraftPayloadInvalid' });
        const failure = new Error('Provider unavailable'), failing = { sha256Hex: async (): Promise<string> => { throw failure; } };
        await expect(prepareOptionEPartialDraftV3(fixture(0), failing)).rejects.toBe(failure);
        await expect(reopenOptionEPartialDraftV3('demo.workplan-draft/v3', fixtures[0].body, fixtures[0].hash, failing)).rejects.toBe(failure);
    });
});
